    useEffect(() => { load() }, []);
    async function create(e) { e.preventDefault(); const form = e.currentTarget, f = new FormData(form), body = { title: f.get('title'), description: f.get('description'), contribution: f.get('contribution'), repositoryUrl: f.get('repositoryUrl') || '', demoUrl: f.get('demoUrl') || '', skills: String(f.get('skills') || '').split(',').map(x => x.trim()).filter(Boolean) }; setBusy('create'); try { if (editing) { const p = await api.patch(`/projects/${editing._id}`, body); setItems(items.map(x => x._id === p._id ? p : x)); setEditing(null); setNotice('Project updated.') } else { const p = await api.post('/projects', body); setItems([p, ...items]); setNotice('Project saved.') } form.reset() } catch (x) { setError(messageOf(x)) } finally { setBusy('') } }
    async function archive(id) { try { await api.delete(`/projects/${id}`); setItems(items.filter(x => x._id !== id)) } catch (e) { setError(messageOf(e)) } }
    async function check(id) { setBusy(id); setError(''); try { const result = await api.post(`/projects/${id}/repository-checks`, {}); setNotice(`${result.meaning} Repository status: ${result.check.status}.`) } catch (e) { setError(messageOf(e)) } finally { setBusy('') } }
    return <><Title eyebrow="YOUR WORK, IN CONTEXT" title="Projects" description="Show what you built, your contribution, and the source links you choose to share." />{error && <div className="error">{error}</div>}{notice && <div className="success"><Check size={15} />{notice}</div>}<div className="workspace-grid"><form className="panel workspace-form" key={editing ? editing._id : 'new'} onSubmit={create}><small>{editing ? 'EDIT PROJECT' : 'ADD A PROJECT'}</small><label>Project title<input name="title" required maxLength="120" defaultValue={editing?.title || ''} /></label><label>What did you build?<textarea name="description" rows="3" maxLength="1500" defaultValue={editing?.description || ''} /></label><label>Your contribution<input name="contribution" maxLength="800" defaultValue={editing?.contribution || ''} placeholder="What you worked on" /></label><label>Skills used<input name="skills" defaultValue={editing?.skills?.join(', ') || ''} placeholder="React, research, prototyping" /></label><label>Repository URL<input name="repositoryUrl" type="url" defaultValue={editing?.repositoryUrl || ''} placeholder="https://github.com/..." /></label><label>Demo URL<input name="demoUrl" type="url" defaultValue={editing?.demoUrl || ''} /></label><Button disabled={busy === 'create'}>{editing ? 'Save project changes' : 'Save project'}</Button>{editing && <Button type="button" secondary onClick={() => setEditing(null)}>Cancel</Button>}</form><div className="workspace-list">{items.map(p => <article className="panel workspace-card" key={p._id}><div className="form-header"><h2>{p.title}</h2><button className="icon-button" aria-label={`Archive ${p.title}`} onClick={() => archive(p._id)}><Trash2 size={16} /></button></div><p>{p.description}</p>{p.contribution && <p><b>Your contribution:</b> {p.contribution}</p>}<div className="tags">{p.skills?.map(s => <span className="chip" key={s}>{s}</span>)}</div><div className="workspace-links"><Button secondary onClick={() => { setEditing(p); window.scrollTo({ top: 0, behavior: 'smooth' }) }}>Edit</Button>{p.repositoryUrl && <a href={p.repositoryUrl} target="_blank" rel="noreferrer">Repository <ExternalLink size={13} /></a>}{p.demoUrl && <a href={p.demoUrl} target="_blank" rel="noreferrer">Demo <ExternalLink size={13} /></a>}{p.repositoryUrl && <Button secondary disabled={busy === p._id} onClick={() => check(p._id)}>{busy === p._id ? 'Checking…' : 'Check public GitHub metadata'}</Button>}</div><small>Metadata check does not verify ownership, authorship, code quality, or project claims.</small></article>)}{!items.length && <div className="panel empty-state">No projects yet. Add one to connect your skills to work you can show.</div>}</div></div></>;
