    async function save(e) { e.preventDefault(); const f = new FormData(e.currentTarget), body = {}; if (f.get('role')) body.role = f.get('role'); if (f.get('status')) body.status = f.get('status'); if (!Object.keys(body).length) { setError('Choose a role or status change first.'); return } try { const u = await api.patch(`/admin/users/${account}/access`, body); setNotice(`Access updated for ${u.name}. They must sign in again.`); const h = await api.get(`/admin/users/${account}/access-history`); setHistory(h) } catch (x) { setError(messageOf(x)) } }
